const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const offer_token = text(input.offer_token);
const mobile = text(input.mobile);
const response = text(input.response).toLowerCase();
const response_note = text(input.response_note);
const confirm_response = toBoolean(input.confirm_response);

const errors = [];

if (!offer_token) {
  errors.push({
    field: 'offer_token',
    message: 'توکن پیشنهاد الزامی است.',
  });
}

if (!mobile) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل بیمار الزامی است.',
  });
}

if (mobile && !/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل باید فقط شامل اعداد و در صورت نیاز علامت + باشد.',
  });
}

if (!['accept', 'decline'].includes(response)) {
  errors.push({
    field: 'response',
    message: 'response باید accept یا decline باشد.',
  });
}

if (response_note.length > 500) {
  errors.push({
    field: 'response_note',
    message: 'یادداشت پاسخ نباید بیشتر از 500 کاراکتر باشد.',
  });
}

if (confirm_response !== true) {
  errors.push({
    field: 'confirm_response',
    message: 'پاسخ بیمار باید به‌صورت صریح تأیید شود.',
  });
}

return [
  {
    json: {
      offer_token,
      mobile,
      response,
      response_note,
      confirm_response,
      validation_status: errors.length === 0 ? 'valid' : 'invalid',
      errors,
    },
  },
];

