const booking = $('Accept Offer and Create Appointment').first().json;
const saved = $json;

return [
  {
    json: {
      ...booking,
      success: true,
      result: 'waitlist_offer_accepted',
      message: 'پیشنهاد پذیرفته، نوبت ثبت و Google Calendar به‌روزرسانی شد.',
      google_calendar_event_id:
        saved.google_calendar_event_id ?? null,
      calendar_sync_status: 'created',
    },
  },
];

const booking = $('Accept Offer and Create Appointment').first().json;

return [
  {
    json: {
      ...booking,
      success: true,
      result: 'waitlist_offer_accepted',
      message: 'پیشنهاد پذیرفته و نوبت ثبت شد، اما ساخت رویداد Google Calendar ناموفق بود.',
      google_calendar_event_id: null,
      calendar_sync_status: 'create_failed',
    },
  },
];

const message =
  $json.error?.message ??
  $json.errorMessage ??
  $json.message ??
  'خطای دیتابیس هنگام ثبت نوبت لیست انتظار رخ داد.';

if (
  String(message).includes(
    'appointment_time_blocked_by_schedule_exception'
  )
) {
  return [
    {
      json: {
        success: false,
        result: 'offered_slot_blocked',
        message: 'زمان پیشنهادی اکنون در برنامه پزشک مسدود شده است.',
      },
    },
  ];
}

return [
  {
    json: {
      success: false,
      result: 'waitlist_booking_database_error',
      message,
    },
  },
];

